export const tldrZh: Record<string, string> = {
  "anal-hsil-precursor": "肛管高级别鳞状上皮内病变是肛管癌由此生长的HPV相关癌前病变，通过细胞学和高分辨率肛门镜筛查高危人群发现。ANCHOR试验显示，在门诊以消融为主治疗这些病变可减少进展为肛管癌的数量，因此现已推荐对HIV感染者进行筛查和治疗。",
  "localised-anal-cancer": "局限期肛管癌是尚未扩散到骨盆和腹股沟以外的肛管鳞状细胞癌，是少数主要靠放化疗而非手术治愈的癌症之一。自ACT II试验以来，放疗期间联合氟尿嘧啶（fluorouracil）和丝裂霉素（mitomycin）一直是标准方案，切除肛门的手术仅留给少数癌症持续存在或复发的患者。",
  "metastatic-anal-cancer": "转移性肛管癌是已扩散到肝、肺或远处淋巴结，或在手术无法切除的部位复发的肛管鳞状细胞癌。InterAACT试验后，卡铂（carboplatin）联合紫杉醇（paclitaxel）成为一线标准；POD1UM-303试验后，PD-1抗体瑞弗利单抗（retifanlimab）于2025年加入该方案；纳武利尤单抗（nivolumab）或帕博利珠单抗（pembrolizumab）是化疗后的选择。",
  "localised-penile-cancer": "局限期阴茎癌是局限于阴茎、尚未扩散到腹股沟淋巴结的鳞状细胞癌，治疗目标是切除肿瘤同时尽可能保留阴茎。癌前病变和小肿瘤采用药膏、激光或保留龟头的手术治疗，腹股沟淋巴结通过前哨淋巴结活检或随访观察，而不是整体清除。",
  "node-positive-penile-cancer": "淋巴结阳性阴茎癌是已到达腹股沟或盆腔淋巴结或扩散更远的阴茎鳞状细胞癌，是阴茎癌威胁生命的阶段。治疗将腹股沟淋巴结清扫与术前或术后化疗或放化疗相结合，InPACT试验正在检验最佳顺序，PD-1抗体正被加入晚期疾病的治疗。",
  "hpv-associated-vulvar-cancer": "HPV相关外阴癌是由持续HPV感染引起的外阴鳞状细胞癌类型，由称为普通型VIN的癌前病变发展而来，以p16蛋白为标志。它多见于较年轻的女性，对放疗反应更好，复发也比非HPV相关型少，并且可以通过HPV疫苗预防。",
  "hpv-independent-vulvar-cancer": "非HPV相关外阴癌是更常见的外阴鳞状细胞癌类型，起源于老年女性的慢性皮肤病硬化性苔藓而非HPV，以p53基因缺陷为标志。它的局部复发远比HPV型频繁，因此治疗以完整手术切除、控制周围皮肤病变和长期随访为核心。",
  "vaginal-squamous-cell-carcinoma": "阴道鳞状细胞癌是最常见的阴道癌类型，由与宫颈癌相同的HPV感染引起，常继发于早先的宫颈病变。它的治疗与宫颈癌大致相同，多数分期采用放疗、近距离放疗和顺铂（cisplatin），手术仅用于阴道上段的小肿瘤，并可通过HPV疫苗和宫颈筛查预防。",
  "vaginal-adenocarcinoma": "阴道腺癌是一种罕见的腺体来源阴道癌，最著名的是母亲在孕期服用己烯雌酚（DES）的年轻女性所患的透明细胞型。与常见的鳞状细胞型不同，它不是由HPV引起，因常见于年轻女性而尽可能采用手术治疗，晚期则使用放疗和铂类化疗。",
  "thymoma": "胸腺瘤是胸腺上皮肿瘤中生长较慢的一类，是胸骨后胸腺的惰性癌症，常以自身免疫病重症肌无力为首发表现。完整手术切除可治愈大多数患者，对突破包膜的肿瘤加用放疗，化疗用于术前缩小大肿瘤或控制胸腔内扩散的疾病。",
  "thymic-carcinoma": "胸腺癌是胸腺上皮肿瘤中侵袭性强的一类，其外观和行为类似其他部位的癌，发现时常已扩散。可行时尝试手术，卡铂（carboplatin）联合紫杉醇（paclitaxel）是常用化疗，激酶抑制剂舒尼替尼（sunitinib）和仑伐替尼（lenvatinib）以及PD-1抗体帕博利珠单抗（pembrolizumab）在试验中显示出疗效，仑伐替尼已在日本获批。",
  "localised-adrenocortical-carcinoma": "局限期肾上腺皮质癌是仍局限于肾上腺及其周围、可通过手术切除的肾上腺皮质癌，手术是唯一能治愈它的治疗。术后，复发风险高的患者接受肾上腺特异性药物米托坦（mitotane）治疗，风险主要根据Ki-67增殖指数和是否完整切除判断，低风险患者则随访观察。",
  "advanced-adrenocortical-carcinoma": "晚期肾上腺皮质癌是已扩散到远处器官或无法切除的肾上腺皮质癌，是最难治疗的内分泌癌之一。标准方案是FIRM-ACT试验确立的米托坦（mitotane）联合依托泊苷（etoposide）、多柔比星（doxorubicin）和顺铂（cisplatin）化疗，有限转移采用手术或消融，激素过多用类固醇阻断药控制，免疫治疗对少数患者有效。",
  "low-grade-appendiceal-mucinous-neoplasm": "低级别阑尾黏液性肿瘤是一种生长缓慢、分泌黏液的阑尾癌，破裂后会以腹膜假黏液瘤的形式将胶冻状物质扩散到整个腹腔。它很少经血液或淋巴扩散，因此采用手术治疗，剥除腹腔内所有可见病灶并用加热化疗液冲洗腹腔，这一手术可使大多数患者获得多年生存。",
  "appendiceal-adenocarcinoma": "阑尾腺癌是阑尾癌中具有侵袭性、形成腺体的类型，其行为更像肠癌而非分泌胶冻的低级别肿瘤，会扩散到淋巴结和腹膜。治疗采用右半结肠切除和肠癌化疗，若已在腹膜扩散，体能良好的患者接受肿瘤细胞减灭术加腹腔热灌注化疗。",
  "goblet-cell-adenocarcinoma": "杯状细胞腺癌是一种罕见的阑尾癌，其细胞兼有充满黏液的杯状细胞和神经内分泌特征，曾称为杯状细胞类癌，现归类并按腺癌治疗。它通过右半结肠切除术切除，高级别或已扩散时给予肠癌化疗，不使用治疗真正神经内分泌肿瘤的生长抑素类药物。",
  "localised-small-bowel-adenocarcinoma": "局限期小肠腺癌是尚未扩散到邻近淋巴结以外、可通过手术切除的十二指肠、空肠或回肠癌，手术是唯一的治愈手段。十二指肠肿瘤需行Whipple手术，更远端的肿瘤行节段切除，淋巴结阳性者术后按结肠癌模式给予化疗，BALLAD试验正在检验其是否真正有益。",
  "advanced-small-bowel-adenocarcinoma": "晚期小肠腺癌是已扩散到肝、腹膜或其他部位的小肠癌，采用肠癌所用的化疗，即奥沙利铂（oxaliplatin）联合氟嘧啶类药物，之后是紫杉类或伊立替康（irinotecan）。重要的例外是相当一部分患者的肿瘤存在错配修复缺陷，对他们而言免疫治疗药物帕博利珠单抗（pembrolizumab）远比化疗有效。",
  "cup-favourable-subsets": "原发灶不明癌的预后良好亚组约占五分之一，即尽管找不到原发肿瘤，但扩散模式、镜下形态或血液标志物强烈指向某种特定癌症的病例。它们按该癌症治疗，例如仅腋窝淋巴结受累的女性按乳腺癌治疗，许多可以治愈或控制多年。",
  "cup-unfavourable": "预后不良的原发灶不明癌占绝大多数病例，即转移性腺癌或低分化癌不符合任何已知模式且找不到起源。长期以来治疗是通用的铂类化疗，但CUPISCO试验显示，在短程化疗后根据肿瘤基因缺陷匹配药物可更长时间控制疾病，免疫治疗对少数患者有效。",
  "erdheim-chester-disease": "Erdheim-Chester病是一种罕见的组织细胞增生症，即称为组织细胞的免疫细胞发生的类似癌症的过度增生，使长骨、肾脏和心脏周围组织、脑和皮肤发生瘢痕化。大多数病例携带BRAF V600E突变或同一生长通路的其他缺陷，最初为黑色素瘤研发的靶向药维莫非尼（vemurafenib）和考比替尼（cobimetinib）现可控制大多数患者的疾病。",
  "rosai-dorfman-disease": "Rosai-Dorfman病是一种罕见的组织细胞增生症，称为组织细胞的大型免疫细胞充满颈部淋巴结，或生长在皮肤、骨、鼻腔、脑膜或肾脏。许多病例无需治疗即可消退，因此除非威胁器官才治疗，此时采用手术、类固醇、西罗莫司，或对约三分之一携带生长通路突变者使用考比替尼（cobimetinib）等MEK抑制剂。",
  "lch-single-system": "单系统朗格汉斯细胞组织细胞增生症是这种罕见组织细胞增生症的较轻形式，异常免疫细胞仅累及儿童或年轻人的一个器官，通常是一块骨或皮肤。单发骨病变常在活检或刮除后自行愈合，皮肤病变可自行消退，长春花碱（vinblastine）加泼尼松的温和化疗留给多发骨病变或靠近脑部的病变。",
  "lch-multisystem": "多系统朗格汉斯细胞组织细胞增生症是这种罕见组织细胞增生症的重症形式，异常细胞同时累及多个器官，最危险的是婴儿的肝、脾和骨髓。治疗为一年的长春花碱（vinblastine）加泼尼松化疗，对反应不快的儿童使用更强的药物或BRAF靶向药，目前生存率已很高，但尿崩症和脑损伤等远期效应仍然存在。",
  "indolent-systemic-mastocytosis": "惰性系统性肥大细胞增多症是这种罕见血液病常见的缓慢类型，因KIT基因突变导致过多肥大细胞在骨髓和皮肤中蓄积，释放组胺等化学物质引起潮红、瘙痒、胃痛、骨质变薄，有时引发严重过敏反应。预期寿命接近正常，治疗长期以抗组胺药和肾上腺素控制症状为主，低剂量靶向药阿伐替尼（avapritinib）于2023年获批用于减轻症状。",
  "advanced-systemic-mastocytosis": "晚期系统性肥大细胞增多症是这种罕见血液癌症的危险类型，KIT突变的肥大细胞损害骨髓、肝、肠道或骨骼，或与慢性粒单核细胞白血病等第二种血液癌症同时生长，或以肥大细胞白血病形式涌入血液。阻断KIT的药物米哚妥林（midostaurin）和阿伐替尼（avapritinib）已取代旧化疗成为首选治疗，体能良好者考虑骨髓移植。",
  "early-stage-classical-hodgkin-lymphoma": "早期经典型霍奇金淋巴瘤是局限于横膈一侧一到两个淋巴结区域的霍奇金淋巴瘤，是最可治愈的癌症之一，大多数患者通过短程ABVD化疗联合或不联合受累淋巴结放疗治愈。由于患者年轻，试验现在利用两个周期后的PET扫描在安全前提下尽量减少治疗。",
  "advanced-stage-classical-hodgkin-lymphoma": "晚期经典型霍奇金淋巴瘤是累及横膈两侧淋巴结或已扩散到肝、肺或骨髓等器官的霍奇金淋巴瘤。治疗为六个周期的联合化疗，近期两项试验改变了标准：以维布妥昔单抗（brentuximab vedotin）替代博来霉素（ECHELON-1），再以免疫治疗药物纳武利尤单抗（nivolumab）替代（SWOG S1826），治愈了更多患者且毒性更低。",
  "nodular-lymphocyte-predominant-hodgkin-lymphoma": "结节性淋巴细胞为主型霍奇金淋巴瘤是经典型霍奇金淋巴瘤罕见、生长缓慢的近亲，其细胞与普通B细胞淋巴瘤一样携带CD20蛋白，差异之大以致WHO在2022年将其重新命名为B细胞淋巴瘤。早期疾病通常仅用放疗即可治愈，儿童甚至仅用手术即可；晚期用含利妥昔单抗（rituximab）的化疗；因其可能在多年后复发，患者需终身随访。",
  "relapsed-refractory-hodgkin-lymphoma": "复发或难治性经典型霍奇金淋巴瘤是一线化疗后复发或无反应的霍奇金淋巴瘤。标准路径是挽救化疗，现常联合维布妥昔单抗（brentuximab vedotin）或PD-1抗体，随后行大剂量化疗加自体干细胞移植；再次复发者使用PD-1抗体纳武利尤单抗（nivolumab）和帕博利珠单抗（pembrolizumab），许多人可获得长期控制。",
  "low-risk-gtn": "低危妊娠滋养细胞肿瘤是这种罕见妊娠相关癌症的轻型，通常在葡萄胎清除后妊娠激素hCG未能下降时发现。几乎每位女性都能通过单药化疗甲氨蝶呤（methotrexate）或放线菌素D（dactinomycin）治愈，用药直至激素水平恢复正常，多数人之后可正常妊娠。",
  "high-risk-gtn": "高危妊娠滋养细胞肿瘤是这种妊娠相关癌症的侵袭型，通常是已扩散到肺、肝或脑并产生极高hCG水平的绒毛膜癌。治疗采用多药EMA-CO化疗方案，对病情最重的女性温和起始以避免早期死亡，大多数女性可治愈；耐药者采用铂类方案、免疫治疗或手术。",
  "placental-site-trophoblastic-tumour": "胎盘部位滋养细胞肿瘤和上皮样滋养细胞肿瘤是妊娠滋养细胞肿瘤中罕见、生长缓慢的类型，起源于固定胎盘的中间型滋养细胞而非产生绒毛膜癌的激素分泌细胞。它们产生的hCG很少，对治愈其他滋养细胞肿瘤的化疗反应差，首选子宫切除治疗，扩散或在妊娠后很久才发生时加用铂类化疗。",
  "hereditary-ppgl": "遗传性嗜铬细胞瘤和副神经节瘤是这类分泌肾上腺素肿瘤的遗传形式，由十余种基因之一的缺陷引起，最常见的是SDHB、SDHD、VHL和RET基因。明确基因会改变治疗：SDHB携带者肿瘤扩散风险最高，VHL和MEN2患者因双侧发病而接受保留肾上腺的手术，亲属在出现症状前接受检测和筛查。",
  "metastatic-ppgl": "转移性嗜铬细胞瘤和副神经节瘤是已扩散到骨、淋巴结、肝或肺的疾病，这是这类分泌肾上腺素的肿瘤被称为恶性的唯一方式。它常进展缓慢，因此治疗从血压控制和观察开始，然后依次采用归巢到肿瘤的放射性药物、FIRSTMAPPP试验证实的激酶抑制剂舒尼替尼（sunitinib）、化疗，以及2025年起的靶向药贝组替凡（belzutifan）。",
  "locoregionally-advanced-nasopharyngeal-carcinoma": "局部区域晚期鼻咽癌是由EB病毒驱动的鼻后腔癌症，已侵入邻近结构或扩散到颈部淋巴结但未及更远。它不靠手术治疗，而是采用精确放疗联合顺铂（cisplatin），现通常先行吉西他滨（gemcitabine）联合顺铂化疗，近期试验中还加入了PD-1免疫治疗，大多数患者可治愈。",
  "recurrent-metastatic-nasopharyngeal-carcinoma": "复发或转移性鼻咽癌是放疗后复发或已扩散到骨、肝或肺的鼻咽癌。吉西他滨（gemcitabine）联合顺铂（cisplatin）是化疗基础，JUPITER-02及后续试验中加入PD-1抗体特瑞普利单抗（toripalimab）、卡瑞利珠单抗（camrelizumab）、替雷利珠单抗（tislelizumab）或派安普利单抗（penpulimab）延长了生存并成为标准，鼻咽局部复发则采用内镜手术或再程放疗。",
  "esthesioneuroblastoma": "嗅神经母细胞瘤是一种罕见的鼻腔和鼻窦癌，起源于鼻顶部紧邻大脑的嗅觉神经上皮。治疗为经鼻或颅底手术后放疗，高级别或广泛肿瘤加用化疗，因其可在十年或更久后复发，患者需终身随访。",
  "sinonasal-undifferentiated-carcinoma": "鼻腔鼻窦未分化癌是一种罕见、生长迅速的鼻腔和鼻窦癌，由无明确分化方向的原始细胞组成，大多数携带IDH2基因突变。它表现为压迫眼或脑的巨大肿块，先行化疗，再根据肿瘤反应选择手术或放化疗；缺失SMARCB1或SMARCA4蛋白的相关肿瘤现被视为独立疾病。",
};
